$('#startLang').addEventListener('click', toggleLang);
$('#btnTheme').addEventListener('click', toggleTheme);

// start screen
$('#btnOpenFolder').addEventListener('click', pickFolder);
$('#btnOpenLast').addEventListener('click', openLast);
