$('#dlgResearcherMap').addEventListener('cancel',e=>{
  // Escape is reserved for clearing the current map focus; the close button remains available.
  e.preventDefault();
  if(!researcherMapState) return;
  researcherMapState.selected=null;
  researcherMapState.hovered=null;
  applyResearcherMapHighlight();
  renderResearcherMapSide();
});
(function(){
  const svg=$('#researcherMapSvg');
  let pan=null,dragNode=null,pressEdge=null,moved=false;
  svg.addEventListener('pointerover',e=>{
    if(!researcherMapState) return;
    const node=e.target.closest('[data-rm-node]'), edge=e.target.closest('[data-rm-edge]');
    const next=node?{type:'node',index:+node.dataset.rmNode}:edge?{type:'edge',index:+edge.dataset.rmEdge}:null;
    if(!next) return;
    researcherMapState.hovered=next; applyResearcherMapHighlight(); renderResearcherMapSide();
  });
  svg.addEventListener('pointerout',e=>{
    if(!researcherMapState || !e.target.closest('[data-rm-node],[data-rm-edge]')) return;
    if(e.relatedTarget && e.relatedTarget.closest && e.relatedTarget.closest('[data-rm-node],[data-rm-edge]')===e.target.closest('[data-rm-node],[data-rm-edge]')) return;
    researcherMapState.hovered=null; applyResearcherMapHighlight(); renderResearcherMapSide();
  });
  svg.addEventListener('pointerdown',e=>{
    const g=researcherMapState; if(!g) return;
    const node=e.target.closest('[data-rm-node]'), edge=e.target.closest('[data-rm-edge]');
    moved=false; pressEdge=null;
    if(node) dragNode={index:+node.dataset.rmNode,x:e.clientX,y:e.clientY};
    else if(edge) pressEdge={index:+edge.dataset.rmEdge,x:e.clientX,y:e.clientY};
    else{pan={x:e.clientX,y:e.clientY,vx:g.view.x,vy:g.view.y};svg.classList.add('panning');}
    svg.setPointerCapture(e.pointerId);
  });
  svg.addEventListener('pointermove',e=>{
    const g=researcherMapState; if(!g) return;
    if(dragNode){
      const n=g.nodes[dragNode.index]; n.x+=(e.clientX-dragNode.x)/g.view.k; n.y+=(e.clientY-dragNode.y)/g.view.k;
      if(Math.abs(e.clientX-dragNode.x)+Math.abs(e.clientY-dragNode.y)>2)moved=true;
      dragNode.x=e.clientX;dragNode.y=e.clientY;g.userView=true;renderResearcherMap();
    }else if(pan){
      if(Math.abs(e.clientX-pan.x)+Math.abs(e.clientY-pan.y)>2)moved=true;
      g.view.x=pan.vx-(e.clientX-pan.x)/g.view.k;g.view.y=pan.vy-(e.clientY-pan.y)/g.view.k;g.userView=true;updateResearcherMapViewBox();
    }else if(pressEdge&&Math.abs(e.clientX-pressEdge.x)+Math.abs(e.clientY-pressEdge.y)>2)moved=true;
  });
  svg.addEventListener('pointerup',e=>{
    const g=researcherMapState;if(!g)return;
    if(dragNode&&!moved) g.selected=g.selected&&g.selected.type==='node'&&g.selected.index===dragNode.index?null:{type:'node',index:dragNode.index};
    else if(pressEdge&&!moved) g.selected=g.selected&&g.selected.type==='edge'&&g.selected.index===pressEdge.index?null:{type:'edge',index:pressEdge.index};
    else if(pan&&!moved){ g.selected=null; g.hovered=null; }
    dragNode=null;pressEdge=null;pan=null;svg.classList.remove('panning');applyResearcherMapHighlight();renderResearcherMapSide();
  });
  svg.addEventListener('wheel',e=>{
    const g=researcherMapState;if(!g||!g.nodes.length)return;
    e.preventDefault();const v=g.view,rect=svg.getBoundingClientRect(),mx=v.x+(e.clientX-rect.left)/v.k,my=v.y+(e.clientY-rect.top)/v.k;
    const k=Math.max(.18,Math.min(4,v.k*(e.deltaY<0?1.04:1/1.04)));
    v.x=mx-(e.clientX-rect.left)/k;v.y=my-(e.clientY-rect.top)/k;v.k=k;g.userView=true;updateResearcherMapViewBox();
  },{passive:false});
  let resizeTimer=null;
  new ResizeObserver(()=>{
    const g=researcherMapState;if(!g)return;
    const wrap=$('#researcherMapCanvasWrap'),W=wrap.clientWidth,H=wrap.clientHeight;
    if(W<200||H<200||(W===g.W&&H===g.H))return;
    g.W=W;g.H=H;updateResearcherMapViewBox();
    if(g.userView)return;
    clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(researcherMapState!==g)return;researcherMapLayout(g.nodes,g.edges,W,H);fitResearcherMapView();renderResearcherMap();},120);
  }).observe($('#researcherMapCanvasWrap'));
})();
/* ---------------------------------------------------------------
   Related-papers graph (Connected Papers style).
   Pool = seed refs + citing works (with their reference lists), scored by
   cosine-normalised bibliographic coupling + co-citation with the seed;
   top-N by relevance become nodes. Edges use normalised coupling so long
   reference lists (reviews) do not dominate the layout.
---------------------------------------------------------------- */
const GRAPH_MAX_NODES = 42;      // seed + neighbours
const GRAPH_MIN_SHARED = 1;      // min shared refs for an edge; later thinned visually
const GRAPH_POOL_CITING = 100;   // citing works pulled into the candidate pool
const GRAPH_POOL_REFS = 100;     // seed references considered (ranked by co-citation)
const GRAPH_CACHE_V = 3;         // bump to invalidate graphs cached without citation direction
let graphState = null;           // { nodes, edges, view, selId, anim }
let graphShowLabels = true;
const GRAPH_PREFS_KEY = 'refshelf.graphPrefs';
// solid | arrow | particle | dash (blue) | dashtrack (blue over gray line) | dashgray (gray, default)
const GRAPH_CITE_STYLES = ['solid','arrow','particle','dash','dashtrack','dashgray'];
let graphCitationStyle = 'dashgray';
// Normal direction is cited paper → citing paper. The reverse button changes
// only this visual convention; the underlying citation relation is unchanged.
let graphReverseDirection = false;
let graphDirectionChosen = false;
let graphZoom = 100;
let graphNodeSpacing = 100;
let graphWheelSensitivity = 50;
let graphAuthorMode = 'last';    // 'last' | 'first' — author shown on node labels
let graphFilterMode = 'hide';    // 'hide' | 'dim' — how non-matching nodes are shown
let graphFilters = null;         // per-open filter state (see resetGraphFilters)
try{
  const graphPrefs = JSON.parse(localStorage.getItem(GRAPH_PREFS_KEY) || '{}');
  if(GRAPH_CITE_STYLES.includes(graphPrefs.style)) graphCitationStyle = graphPrefs.style;
  if(graphPrefs.authorMode==='first' || graphPrefs.authorMode==='last') graphAuthorMode = graphPrefs.authorMode;
  if(graphPrefs.filterMode==='hide' || graphPrefs.filterMode==='dim') graphFilterMode = graphPrefs.filterMode;
  graphDirectionChosen = graphPrefs.reverseChoice === true;
  if(graphDirectionChosen){
    // v2 called cited → citing "reversed". Preserve the visible direction
    // while migrating to v3, where that direction is the normal convention.
    graphReverseDirection = graphPrefs.v >= 3 ? !!graphPrefs.reverse : !graphPrefs.reverse;
  }
  const savedZoom = Number.isFinite(+graphPrefs.zoom) ? +graphPrefs.zoom : +graphPrefs.spread;
  if(Number.isFinite(savedZoom)) graphZoom = Math.max(70, Math.min(180, savedZoom));
  if(Number.isFinite(+graphPrefs.spacing)) graphNodeSpacing = Math.max(80, Math.min(180, +graphPrefs.spacing));
  if(Number.isFinite(+graphPrefs.wheel)) graphWheelSensitivity = Math.max(20, Math.min(100, +graphPrefs.wheel));
}catch(e){}
function saveGraphPrefs(){
  try{ localStorage.setItem(GRAPH_PREFS_KEY, JSON.stringify({v:4, style:graphCitationStyle, reverse:graphReverseDirection, reverseChoice:graphDirectionChosen, zoom:graphZoom, spacing:graphNodeSpacing, wheel:graphWheelSensitivity, authorMode:graphAuthorMode, filterMode:graphFilterMode})); }catch(e){}
}

// Fetch works by OpenAlex id: batched list queries first (1 request / 50 ids),
// falling back to the un-metered single-entity endpoint for chunks the list
// tier could not serve (rate limit etc.). Calls cb(work) for each record.
async function fetchWorksByIds(ids, select, cb){
  const missing = [];
  for(let i=0; i<ids.length; i+=50){
    const chunk = ids.slice(i, i+50);
    try{
      const d = await oaFetch('works?per-page=50&select=' + select + '&filter=openalex:' + chunk.join('|'));
      (d.results||[]).forEach(cb);
    }catch(e){ missing.push(...chunk); }
  }
  const CONC = 6;
  let idx = 0;
  async function worker(){
    while(idx < missing.length){
      const id = missing[idx++];
      try{ cb(await oaFetch('works/' + id + '?select=' + select)); }
      catch(e){ /* skip this candidate */ }
    }
  }
  await Promise.all(Array.from({length:Math.min(CONC, missing.length)}, worker));
}

function sharedCount(a, b){
  let n = 0;
  const small = a.size < b.size ? a : b;
  const large = small===a ? b : a;
  small.forEach(r=>{ if(large.has(r)) n++; });
  return n;
}
// cosine-normalised bibliographic coupling: shared / sqrt(|A|·|B|)
function couplingSim(shared, sizeA, sizeB){
  return (shared && sizeA && sizeB) ? shared / Math.sqrt(sizeA * sizeB) : 0;
}

async function buildGraphData(seedItem, onProgress){
  onProgress(t('graphLoading1'));
  const seedWork = await resolveOpenAlexWork(seedItem); // single-entity, throws if not found
  const seedId = oaId(seedWork.id);
  const refIds = (seedWork.referenced_works||[]).map(oaId).filter(id=>id!==seedId);
  const seedRefs = new Set(refIds);

  // ---- candidate pool (light select: reference lists drive the scoring) ----
  const POOL_SELECT = 'id,referenced_works,cited_by_count';
  const pool = new Map();   // id -> { refs:Set, cited }
  const addPool = (w)=>{
    const id = oaId(w.id);
    if(!id || id===seedId || pool.has(id)) return;
    pool.set(id, { refs:new Set((w.referenced_works||[]).map(oaId)), cited:w.cited_by_count||0 });
  };
  // citing works — one list query; optional (skipped if rate-limited)
  let citingList = [];
  try{
    const d = await oaFetch('works?per-page=' + GRAPH_POOL_CITING + '&sort=cited_by_count:desc&select=' + POOL_SELECT + '&filter=cites:' + seedId);
    citingList = d.results||[];
  }catch(e){ /* citing list optional under budget limits */ }
  citingList.forEach(addPool);
  // co-citation with the seed: how often each work appears in a citing work's
  // reference list alongside the seed
  const cocit = new Map();  // id -> count
  citingList.forEach(w=>{
    (w.referenced_works||[]).forEach(r=>{
      const id = oaId(r);
      if(id && id!==seedId) cocit.set(id, (cocit.get(id)||0)+1);
    });
  });
  // seed references: rank by co-citation before capping, so the refs most
  // entangled with the seed's citation neighbourhood survive the cut
  const refPick = refIds.slice()
    .sort((a,b)=>(cocit.get(b)||0)-(cocit.get(a)||0))
    .slice(0, GRAPH_POOL_REFS)
    .filter(id=>!pool.has(id));
  onProgress(t('graphLoading2'));
  await fetchWorksByIds(refPick, POOL_SELECT, addPool);

  // ---- score pool: coupling + co-citation (+ tiny prominence tie-breaker) ----
  const maxCocit = Math.max(1, ...Array.from(pool.keys(), id=>cocit.get(id)||0));
  const maxCited = Math.max(10, ...Array.from(pool.values(), p=>p.cited));
  const scored = [];
  pool.forEach((p, id)=>{
    const coupling = couplingSim(sharedCount(p.refs, seedRefs), p.refs.size, seedRefs.size);
    const co = (cocit.get(id)||0) / maxCocit;
    const prominence = Math.log10(1+p.cited) / Math.log10(1+maxCited);
    scored.push({ id, score: coupling + 0.8*co + 0.08*prominence });
  });
  scored.sort((a,b)=>b.score-a.score);
  const chosenIds = scored.slice(0, GRAPH_MAX_NODES-1).map(s=>s.id);

  // ---- full metadata for the chosen candidates only ----
  const works = new Map();  // id -> work (with referenced_works)
  await fetchWorksByIds(chosenIds, OA_SELECT, w=>{ const id = oaId(w.id); if(id && id!==seedId) works.set(id, w); });
  const fetchFailed = chosenIds.length - works.size;

  // nodes: seed + every candidate we managed to fetch
  const nodes = [{ id:seedId, w:seedWork, wRefs:seedRefs, seed:true }];
  works.forEach((w, id)=>{
    nodes.push({ id, w, wRefs:new Set((w.referenced_works||[]).map(oaId)), seed:false });
  });
  nodes.forEach(n=>{
    n.item = openAlexToItem(n.w);
    n.year = parseInt(n.item.year,10) || null;
    n.cited = n.w.cited_by_count || 0;
    n.label = graphNodeLabel(n);
    n.seedRel = n.seed ? null : {
      shared: sharedCount(n.wRefs, seedRefs),
      citesSeed: n.wRefs.has(seedId),
      citedBySeed: seedRefs.has(n.id)
    };
  });
  // edges: normalised bibliographic coupling between node pairs + direct citations
  const edges = [];
  for(let i=0;i<nodes.length;i++){
    for(let j=i+1;j<nodes.length;j++){
      const A = nodes[i], B = nodes[j];
      const shared = sharedCount(A.wRefs, B.wRefs);
      const citeAToB = A.wRefs.has(B.id);
      const citeBToA = B.wRefs.has(A.id);
      const direct = citeAToB || citeBToA;
      if(shared >= GRAPH_MIN_SHARED || direct){
        edges.push({
          a:i, b:j,
          w: couplingSim(shared, A.wRefs.size, B.wRefs.size) + (direct ? 0.25 : 0),
          shared, direct, citeAToB, citeBToA
        });
      }
    }
  }
  return { nodes, edges, fetchFailed };
}

// Reduce the hairball: keep a maximum spanning tree (connectivity via the
// strongest links) plus each node's top-2 strongest edges.
function thinEdges(nodes, edges){
  if(edges.length <= nodes.length) return edges;
  const sorted = edges.slice().sort((a,b)=>b.w - a.w);
  const keep = new Set();
  // max spanning tree (Kruskal + union-find)
  const parent = nodes.map((_,i)=>i);
  const find = (x)=>{ while(parent[x]!==x){ parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  sorted.forEach(e=>{
    const ra = find(e.a), rb = find(e.b);
    if(ra!==rb){ parent[ra] = rb; keep.add(e); }
  });
  // + top-3 strongest per node so local clusters remain readable
  const byNode = new Map();
  sorted.forEach(e=>{
    for(const v of [e.a, e.b]){
      if(!byNode.has(v)) byNode.set(v, []);
      byNode.get(v).push(e);
    }
  });
  byNode.forEach(list=>{ list.slice(0,3).forEach(e=>keep.add(e)); });
  return edges.filter(e=>keep.has(e));
}

// Keep a stable 100% layout and move only node/label coordinates for the
// spacing control. Circle radii and font sizes do not scale, so increasing
// this value creates real whitespace rather than behaving like camera zoom.
function applyGraphNodeSpacing(nodes, W, H){
  const factor = graphNodeSpacing / 100;
  const cx = W/2, cy = H/2;
  nodes.forEach(n=>{
    if(!Number.isFinite(n.layoutX)) n.layoutX = n.x;
    if(!Number.isFinite(n.layoutY)) n.layoutY = n.y;
    n.x = cx + (n.layoutX-cx) * factor;
    n.y = cy + (n.layoutY-cy) * factor;
  });
}

function graphLayout(nodes, edges, W, H, iterations){
  // simple force-directed layout (repulsion + edge springs + centering)
  const N = nodes.length;
  nodes.forEach((n,i)=>{
    if(n.seed){ n.x = 0; n.y = 0; }
    else{
      // jittered start so "re-layout" explores a genuinely different arrangement
      const a = (i / N) * Math.PI * 2 + (Math.random() - 0.5) * 0.9;
      const r = 100 + (i % 5) * 30 + Math.random() * 50;
      n.x = Math.cos(a) * r; n.y = Math.sin(a) * r;
    }
    n.vx = 0; n.vy = 0;
  });
  const maxW = Math.max(1, ...edges.map(e=>e.w));
  const maxCited = Math.max(...nodes.map(n=>n.cited));
  const radii = nodes.map(n=>graphNodeR(n.cited, maxCited));
  for(let it=0; it<(iterations||260); it++){
    const temp = 1 - it/(iterations||260);
    // repulsion
    for(let i=0;i<N;i++) for(let j=i+1;j<N;j++){
      const A = nodes[i], B = nodes[j];
      let dx = A.x-B.x, dy = A.y-B.y;
      let d2 = dx*dx + dy*dy || 0.01;
      const d = Math.sqrt(d2);
      const ux = dx/d, uy = dy/d;
      if(d2 < 90000){
        const f = 2600 / d2;
        A.vx += ux*f; A.vy += uy*f;
        B.vx -= ux*f; B.vy -= uy*f;
      }
      // Keep paper nodes from collapsing into a dense, unreadable clump. The
      // margin follows their actual radii, so large highly-cited papers retain
      // enough breathing room too.
      const minD = radii[i] + radii[j] + 20;
      if(d < minD){
        const push = (minD-d) * 0.13;
        A.vx += ux*push; A.vy += uy*push;
        B.vx -= ux*push; B.vy -= uy*push;
      }
    }
    // springs
    edges.forEach(e=>{
      const A = nodes[e.a], B = nodes[e.b];
      const dx = B.x-A.x, dy = B.y-A.y;
      const d = Math.sqrt(dx*dx+dy*dy) || 0.01;
      const target = 150 - 70 * (e.w / maxW);   // stronger edge → shorter
      const f = (d - target) * 0.02 * (0.5 + e.w / maxW);
      A.vx += dx/d*f; A.vy += dy/d*f;
      B.vx -= dx/d*f; B.vy -= dy/d*f;
    });
    // centering + integrate
    nodes.forEach(n=>{
      n.vx -= n.x * 0.012; n.vy -= n.y * 0.012;
      if(n.seed){ n.vx *= 0.2; n.vy *= 0.2; } // keep seed near center
      n.x += Math.max(-14, Math.min(14, n.vx * temp));
      n.y += Math.max(-14, Math.min(14, n.vy * temp));
      n.vx *= 0.6; n.vy *= 0.6;
    });
  }
  // fit into viewport
  const xs = nodes.map(n=>n.x), ys = nodes.map(n=>n.y);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  const pad = 56;
  const sc = Math.min((W-2*pad)/Math.max(1,maxX-minX), (H-2*pad)/Math.max(1,maxY-minY), 2.2);
  nodes.forEach(n=>{
    n.x = (n.x - (minX+maxX)/2) * sc + W/2;
    n.y = (n.y - (minY+maxY)/2) * sc + H/2;
    n.layoutX = n.x;
    n.layoutY = n.y;
  });
  applyGraphNodeSpacing(nodes, W, H);
}

// Node label = chosen author's family name + year. Last author is the default
// (corresponding/PI convention); the toolbar toggle switches to first author.
function graphNodeLabel(n){
  const authors = (n.item && n.item.authors) || [];
  const pick = graphAuthorMode==='first' ? authors[0] : authors[authors.length-1];
  const fam = (pick && (pick.family || pick.name)) || '';
  return fam + (n.year ? ' ' + n.year : '');
}
function applyGraphLabels(){
  if(!graphState) return;
  graphState.nodes.forEach(n=>{ n.label = graphNodeLabel(n); });
}

// ---- node filtering ---------------------------------------------------------
function resetGraphFilters(){
  graphFilters = { reg:'all', yearMin:'', yearMax:'', citedMin:'', journal:[], author:'', tag:'', coll:'' };
}
// Locate the library item backing a graph node (same match keys as isInLibrary),
// so tag / collection / registration filters can read the stored metadata.
function graphLibItem(it){
  if(!it) return null;
  if(it.doi){ const m = lib.items.find(x=>x.doi && x.doi===it.doi); if(m) return m; }
  if(it.arxiv){ const m = lib.items.find(x=>x.arxiv===it.arxiv); if(m) return m; }
  const key = (it.title||'').toLowerCase().trim();
  return key ? lib.items.find(x=>(x.title||'').toLowerCase().trim()===key) : null;
}
function graphFilterActive(){
  const f = graphFilters;
  return !!(f && (f.reg!=='all' || f.yearMin || f.yearMax || f.citedMin || (f.journal && f.journal.length) || f.author || f.tag || f.coll));
}
function graphNodeMatches(n){
  const f = graphFilters;
  if(!f || n.seed) return true; // the seed is always shown
  const libIt = (f.reg!=='all' || f.tag || f.coll) ? graphLibItem(n.item) : null;
  if(f.reg==='in' && !libIt) return false;
  if(f.reg==='out' && libIt) return false;
  const y = n.year;
  if(f.yearMin && (!y || y < +f.yearMin)) return false;
  if(f.yearMax && (!y || y > +f.yearMax)) return false;
  if(f.citedMin && (n.cited||0) < +f.citedMin) return false;
  if(f.journal && f.journal.length && !f.journal.includes(n.item.journal||'')) return false;
  if(f.author){
    const q = f.author.toLowerCase();
    const hit = (n.item.authors||[]).some(a=>`${a.family||''} ${a.given||''} ${a.name||''}`.toLowerCase().includes(q));
    if(!hit) return false;
  }
  if(f.tag && !(libIt && (libIt.tags||[]).includes(f.tag))) return false;
  if(f.coll && !(libIt && (libIt.collections||[]).includes(f.coll))) return false;
  return true;
}
// Hide or dim non-matching nodes/labels/edges. Class toggling only (no
// re-render), and orthogonal to the selection-based .dim highlight.
function applyGraphFilters(){
  const g = graphState;
  if(!g) return;
  const svg = $('#graphSvg');
  const active = graphFilterActive();
  const on = graphFilterMode==='dim' ? 'gfDim' : 'gfHide';
  const off = graphFilterMode==='dim' ? 'gfHide' : 'gfDim';
  const matched = g.nodes.map(n=>!active || graphNodeMatches(n));
  const setCls = (el, hide)=>{ el.classList.remove(off); el.classList.toggle(on, hide); };
  svg.querySelectorAll('[data-node]').forEach(el=>setCls(el, !matched[+el.dataset.node]));
  svg.querySelectorAll('[data-lbl]').forEach(el=>setCls(el, !matched[+el.dataset.lbl]));
  svg.querySelectorAll('[data-e]').forEach(el=>{ const e=g.edges[+el.dataset.e]; setCls(el, !(matched[e.a] && matched[e.b])); });
  svg.querySelectorAll('[data-cite-e]').forEach(el=>{ const e=g.edges[+el.dataset.citeE]; setCls(el, !(matched[e.a] && matched[e.b])); });
  const fc = $('#graphFilterCount');
  if(fc) fc.textContent = active ? I18N[lang].graphFilterCount(matched.filter(Boolean).length, g.nodes.length) : '';
  const btn = $('#btnGraphFilter');
  if(btn) btn.classList.toggle('active', active);
}
function readGraphFilters(){
  if(!graphFilters) resetGraphFilters();
  const val = (id)=>{ const el = $('#'+id); return el ? el.value.trim() : ''; };
  graphFilters.reg = val('gfReg') || 'all';
  graphFilters.yearMin = val('gfYearMin');
  graphFilters.yearMax = val('gfYearMax');
  graphFilters.citedMin = val('gfCitedMin');
  const jBox = $('#gfJournal');
  graphFilters.journal = jBox ? Array.from(jBox.querySelectorAll('input:checked'), i=>i.value) : [];
  graphFilters.author = val('gfAuthor');
  graphFilters.tag = val('gfTag');
  graphFilters.coll = val('gfColl');
  applyGraphFilters();
}
// Fill tag/collection dropdowns from the current library and reset every control
// to the (empty) graphFilters state. Called each time the dialog opens.
function populateGraphFilterPanel(){
  resetGraphFilters();
  const tags = [...new Set(lib.items.flatMap(x=>x.tags||[]).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const tagSel = $('#gfTag');
  if(tagSel) tagSel.innerHTML = `<option value="">${esc(t('graphFilterAny'))}</option>` + tags.map(tg=>`<option value="${esc(tg)}">${esc(tg)}</option>`).join('');
  const colls = (lib.collections||[]).slice().sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  const collSel = $('#gfColl');
  if(collSel) collSel.innerHTML = `<option value="">${esc(t('graphFilterAny'))}</option>` + colls.map(c=>`<option value="${esc(c.id)}">${esc(c.name||'')}</option>`).join('');
  ['gfYearMin','gfYearMax','gfCitedMin','gfAuthor'].forEach(id=>{ const el=$('#'+id); if(el) el.value=''; });
  const reg = $('#gfReg'); if(reg) reg.value = 'all';
  const jSel = $('#gfJournal'); if(jSel) jSel.innerHTML = ''; // filled once graph data is ready
  updateGraphFilterModeUI();
  const fc = $('#graphFilterCount'); if(fc) fc.textContent = '';
  const btn = $('#btnGraphFilter'); if(btn) btn.classList.remove('active');
}
// Journal is a checkbox list drawn from the journals actually present in the
// current graph — populated once the node data is ready (not on dialog open).
// A plain checkbox list is used instead of <select multiple>, which needs
// modifier-clicks to pick more than one and is easy to mis-operate.
function populateGraphJournalOptions(){
  const box = $('#gfJournal');
  if(!box || !graphState) return;
  const journals = [...new Set(graphState.nodes.map(n=>n.item && n.item.journal).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  box.innerHTML = journals.map(j=>`<label class="gfpCheck"><input type="checkbox" value="${esc(j)}"><span>${esc(j)}</span></label>`).join('');
  if(graphFilters) graphFilters.journal = [];
}
function updateGraphFilterModeUI(){
  document.querySelectorAll('#graphFilterPanel [data-gfmode]').forEach(b=>{
    const on = b.dataset.gfmode===graphFilterMode;
    b.classList.toggle('active', on);
    b.setAttribute('aria-pressed', String(on));
  });
}

function graphYearColor(year, minY, maxY){
  if(!year) return '#9ca3af';
  const f = maxY>minY ? (year-minY)/(maxY-minY) : 0.5;
  // higher-contrast ramp on light bg: sky blue → indigo → deep violet
  const h = 205 + f*72, s = 80 - f*10, l = 68 - f*28;
  return `hsl(${h.toFixed(0)},${s.toFixed(0)}%,${l.toFixed(0)}%)`;
}
function graphNodeR(cited, maxCited){
  return 6 + 16 * Math.sqrt(Math.log10(1+cited) / Math.log10(1+Math.max(10,maxCited)));
}
function graphEdgeShared(e){ return e.shared!=null ? e.shared : Math.max(0, (e.w||0) - (e.direct ? 2 : 0)); }
function graphCitationSegment(from, to, fromR, toR, offset){
  const dx = to.x-from.x, dy = to.y-from.y;
  const d = Math.sqrt(dx*dx+dy*dy) || 1;
  const ux = dx/d, uy = dy/d;
  const ox = -uy*(offset||0), oy = ux*(offset||0);
  return {
    // Leave only a hairline gap at each node. Keeping the target endpoint just
    // outside the circle lets an SVG marker remain visible instead of being
    // painted over by the node itself.
    x1:from.x + ux*(fromR+1) + ox,
    y1:from.y + uy*(fromR+1) + oy,
    x2:to.x - ux*(toR+2) + ox,
    y2:to.y - uy*(toR+2) + oy
  };
}
function graphSeedRelation(g, idx){
  const n = g.nodes[idx];
  if(!n || n.seed) return null;
  if(n.seedRel) return n.seedRel;
  const seedIdx = g.nodes.findIndex(x=>x.seed);
  const e = g.edges.find(x=>(x.a===seedIdx && x.b===idx) || (x.b===seedIdx && x.a===idx));
  return e ? { shared:graphEdgeShared(e), citesSeed:false, citedBySeed:false } : { shared:0, citesSeed:false, citedBySeed:false };
}
function graphRelationText(rel){
  const parts = [];
  if(rel.citesSeed) parts.push(t('graphDirectCites'));
  if(rel.citedBySeed) parts.push(t('graphDirectCitedBy'));
  if(rel.shared) parts.push(I18N[lang].graphSharedRefs(rel.shared));
  return parts.length ? parts.join(' / ') : I18N[lang].graphSharedRefs(0);
}
function graphNearestLinks(g, idx){
  return g.edges
    .filter(e=>e.a===idx || e.b===idx)
    .sort((a,b)=>b.w-a.w)
    .slice(0,4)
    .map(e=>{
      const otherIdx = e.a===idx ? e.b : e.a;
      return { node:g.nodes[otherIdx], edge:e };
    });
}
function fitGraphView(pad, useDisplayedPositions){
  const g = graphState;
  if(!g || !g.nodes.length) return;
  const rs = g.nodes.map(n=>graphNodeR(n.cited, Math.max(...g.nodes.map(x=>x.cited))));
  const nodeX = n=>useDisplayedPositions ? n.x : (Number.isFinite(n.layoutX) ? n.layoutX : n.x);
  const nodeY = n=>useDisplayedPositions ? n.y : (Number.isFinite(n.layoutY) ? n.layoutY : n.y);
  const minX = Math.min(...g.nodes.map((n,i)=>nodeX(n)-rs[i])), maxX = Math.max(...g.nodes.map((n,i)=>nodeX(n)+rs[i]));
  const minY = Math.min(...g.nodes.map((n,i)=>nodeY(n)-rs[i])), maxY = Math.max(...g.nodes.map((n,i)=>nodeY(n)+rs[i]));
  const boxW = Math.max(1, maxX-minX), boxH = Math.max(1, maxY-minY);
  const p = pad == null ? 46 : pad;
  const fitK = Math.min((g.W - p*2)/boxW, (g.H - p*2)/boxH);
  const k = Math.max(0.3, Math.min(5, fitK * graphZoom / 100));
  // centre the bounding box on both axes — the non-constraining axis has slack,
  // and clamping k can leave asymmetric padding otherwise
  g.view = { x: minX - (g.W/k - boxW)/2, y: minY - (g.H/k - boxH)/2, k };
}
function updateGraphStats(){
  const el = $('#graphStats');
  if(!el || !graphState){ if(el) el.textContent = ''; return; }
  el.textContent = I18N[lang].graphStats(graphState.nodes.length, graphState.edges.length);
}
// Paint the filled portion of a range slider (matches the researcher-map look).
function setGraphSliderFill(el){
  if(!el) return;
  const min = +el.min || 0, max = +el.max || 100, v = +el.value;
  const pct = max>min ? ((v-min)/(max-min))*100 : 0;
  el.style.setProperty('--gf-fill', pct.toFixed(2)+'%');
}
function updateGraphCitationControls(){
  const select = $('#graphCitationStyle');
  if(select) select.value = graphCitationStyle;
  const authorSel = $('#graphAuthorMode');
  if(authorSel) authorSel.value = graphAuthorMode;
  const labelsBtn = $('#btnGraphLabels');
  if(labelsBtn){ labelsBtn.classList.toggle('on', graphShowLabels); labelsBtn.setAttribute('aria-checked', String(graphShowLabels)); }
  const reverseBtn = $('#btnGraphReverse');
  if(reverseBtn){
    // the reverse toggle only makes sense for the directional styles; the plain
    // gray line hides citation direction entirely, so hide it there
    reverseBtn.hidden = graphCitationStyle==='solid';
    reverseBtn.classList.toggle('active', graphReverseDirection);
    reverseBtn.setAttribute('aria-pressed', String(graphReverseDirection));
    const key = graphReverseDirection ? 'graphReverseOn' : 'graphReverse';
    reverseBtn.title = t(key);
    const label = $('#graphReverseLabel'); if(label) label.textContent = t(key);
  }
  const zoom = $('#graphZoom');
  if(zoom){ zoom.value = String(graphZoom); setGraphSliderFill(zoom); }
  const zoomValue = $('#graphZoomValue');
  if(zoomValue) zoomValue.textContent = I18N[lang].graphZoomValue(graphZoom);
  const wheel = $('#graphWheelSensitivity');
  if(wheel){ wheel.value = String(graphWheelSensitivity); setGraphSliderFill(wheel); }
  const wheelValue = $('#graphWheelSensitivityValue');
  if(wheelValue) wheelValue.textContent = I18N[lang].graphWheelValue(graphWheelSensitivity);
  const spacing = $('#graphNodeSpacing');
  if(spacing){ spacing.value = String(graphNodeSpacing); setGraphSliderFill(spacing); }
  const spacingValue = $('#graphNodeSpacingValue');
  if(spacingValue) spacingValue.textContent = I18N[lang].graphSpacingValue(graphNodeSpacing);
  const legend = $('#graphCitationLegend');
  const legendText = $('#graphCitationLegendText');
  if(legend) legend.className = `glCitation gl${graphCitationStyle}`;
  if(legendText){
    const key = graphCitationStyle==='solid' ? 'graphLegendSolid' :
      graphCitationStyle==='arrow' ? 'graphLegendArrow' :
      graphCitationStyle==='particle' ? 'graphLegendParticle' : 'graphLegendDash';
    legendText.textContent = graphCitationStyle==='solid' ? t(key) : t(key) + t(graphReverseDirection ? 'graphDirectionReversed' : 'graphDirectionNormal');
  }
}

// pan / zoom / resize only move the camera — updating the viewBox is enough,
// no need to rebuild the SVG DOM
function updateGraphViewBox(){
  const g = graphState;
  if(!g) return;
  $('#graphSvg').setAttribute('viewBox', `${g.view.x} ${g.view.y} ${g.W/g.view.k} ${g.H/g.view.k}`);
}
function renderGraph(){
  const g = graphState;
  if(!g) return;
  applyGraphLabels();
  const svg = $('#graphSvg');
  updateGraphViewBox();
  svg.classList.toggle('hideLabels', !graphShowLabels);
  const years = g.nodes.map(n=>n.year).filter(Boolean);
  const minY = Math.min(...years), maxY = Math.max(...years);
  $('#glYears').textContent = years.length ? `${minY}–${maxY}` : '';
  const maxCited = Math.max(...g.nodes.map(n=>n.cited));
  const citationStyle = graphCitationStyle;
  const nodeRadii = g.nodes.map(n=>Math.max(graphNodeR(n.cited, maxCited), n.seed ? 13 : 0));
  const maxW = Math.max(1, ...g.edges.map(e=>e.w));
  // 'dashtrack' intentionally keeps the gray base line beneath the flow; the
  // other flow styles hide it so a solid line does not show through the dashes.
  const baseUnderCite = citationStyle==='solid' || citationStyle==='dashtrack';
  const edgeHtml = g.edges.map((e,ei)=>{
    if(!baseUnderCite && (e.citeAToB || e.citeBToA)) return '';
    if(!graphEdgeShared(e) && citationStyle!=='solid') return '';
    const A = g.nodes[e.a], B = g.nodes[e.b];
    const title = graphEdgeShared(e) ? I18N[lang].graphSharedRefs(graphEdgeShared(e)) : '';
    return `<line class="gEdge${!graphEdgeShared(e) ? ' directOnly' : ''}" data-e="${ei}" x1="${A.x.toFixed(1)}" y1="${A.y.toFixed(1)}" x2="${B.x.toFixed(1)}" y2="${B.y.toFixed(1)}" stroke-width="${(0.7 + 2.8*e.w/maxW).toFixed(2)}" opacity="${(0.18 + 0.4*e.w/maxW).toFixed(2)}">${title ? `<title>${esc(title)}</title>` : ''}</line>`;
  }).join('');
  const citeHtml = citationStyle==='solid' ? '' : g.edges.map((e,ei)=>{
    if(!e.citeAToB && !e.citeBToA) return '';
    const mutualOffset = e.citeAToB && e.citeBToA ? 3.5 : 0;
    const flows = [];
    const addFlow = (citingIdx, citedIdx)=>{
      const fromIdx = graphReverseDirection ? citingIdx : citedIdx;
      const toIdx = graphReverseDirection ? citedIdx : citingIdx;
      const from = g.nodes[fromIdx], to = g.nodes[toIdx];
      const p = graphCitationSegment(from, to, nodeRadii[fromIdx], nodeRadii[toIdx], mutualOffset);
      const fromLabel = from.label || from.item.title || '';
      const toLabel = to.label || to.item.title || '';
      const dx = p.x2-p.x1, dy = p.y2-p.y1;
      const duration = Math.max(1.25, Math.min(2.8, Math.sqrt(dx*dx+dy*dy)/135));
      const path = `M ${p.x1.toFixed(1)} ${p.y1.toFixed(1)} L ${p.x2.toFixed(1)} ${p.y2.toFixed(1)}`;
      const title = esc(I18N[lang].graphCitationTitle(fromLabel,toLabel,graphReverseDirection));
      const line = `data-cite-e="${ei}" x1="${p.x1.toFixed(1)}" y1="${p.y1.toFixed(1)}" x2="${p.x2.toFixed(1)}" y2="${p.y2.toFixed(1)}"`;
      if(citationStyle==='arrow') flows.push(`<line class="gCiteArrowLine" ${line} marker-end="url(#gCiteArrow)"><title>${title}</title></line>`);
      else if(citationStyle==='particle') flows.push(
        `<line class="gCiteTrack" ${line}><title>${title}</title></line>`+
        `<circle class="gCiteParticle" data-cite-e="${ei}" r="2.8" filter="url(#gCiteGlow)"><animateMotion dur="${duration.toFixed(2)}s" begin="${(-duration*.12).toFixed(2)}s" repeatCount="indefinite" path="${path}"></animateMotion></circle>`
      );
      // dash family: only the moving dashes (dashgray colours them gray). The
      // optional gray base line is drawn separately by edgeHtml for dashtrack.
      else flows.push(`<line class="gCiteFlow${citationStyle==='dashgray'?' gCiteGray':''}" ${line}><title>${title}</title></line>`);
    };
    if(e.citeAToB) addFlow(e.a, e.b);
    if(e.citeBToA) addFlow(e.b, e.a);
    return flows.join('');
  }).join('');
  const nodeHtml = g.nodes.map((n,i)=>{
    // the seed gets a size floor — a modestly-cited seed must not vanish among
    // the classics it pulled in
    const r = nodeRadii[i];
    const fill = graphYearColor(n.year, minY, maxY);
    const inLib = isInLibrary(n.item);
    const cls = ['gNode', n.seed?'seed':'', (!n.seed && inLib)?'inlib':''].filter(Boolean).join(' ');
    return `<g class="${cls}" data-node="${i}" transform="translate(${n.x.toFixed(1)},${n.y.toFixed(1)})">`+
      (n.seed ? `<circle class="gSeedHalo" r="${(r+5).toFixed(1)}"></circle>` : '')+
      `<circle r="${r.toFixed(1)}" fill="${fill}"><title>${esc(n.item.title)}</title></circle></g>`+
      `<text class="gLabel${n.seed?' seed':''}" data-lbl="${i}" x="${n.x.toFixed(1)}" y="${(n.y + r + (n.seed?16:10)).toFixed(1)}" text-anchor="middle">${esc(n.label)}</text>`;
  }).join('');
  svg.innerHTML = `<defs><filter id="gCiteGlow" x="-150%" y="-150%" width="400%" height="400%"><feGaussianBlur stdDeviation="2.2" result="blur"></feGaussianBlur><feMerge><feMergeNode in="blur"></feMergeNode><feMergeNode in="SourceGraphic"></feMergeNode></feMerge></filter><marker id="gCiteArrow" class="gCiteArrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0,0 L8,4 L0,8 Z"></path></marker></defs><g>${edgeHtml}${citeHtml}${nodeHtml}</g>`;
  // the seed must never hide behind a bigger neighbour
  const seedIdx = g.nodes.findIndex(n=>n.seed);
  if(seedIdx >= 0){
    const sl = svg.querySelector(`[data-lbl="${seedIdx}"]`);
    if(sl) sl.parentNode.appendChild(sl);
    const sn = svg.querySelector(`[data-node="${seedIdx}"]`);
    if(sn) sn.parentNode.appendChild(sn);
  }
  updateGraphStats();
  updateGraphCitationControls();
  applyHighlight();
  applyGraphFilters();
}
// Dim everything except the selected node and its neighbours.
// Class toggling only — no re-render, so it is cheap.
function applyHighlight(){
  const g = graphState;
  if(!g) return;
  const svg = $('#graphSvg');
  svg.querySelectorAll('.gNode.sel').forEach(el=>el.classList.remove('sel'));
  if(g.selIdx!=null){
    const el = svg.querySelector(`[data-node="${g.selIdx}"]`);
    if(el){
      el.classList.add('sel');
      // raise above neighbouring nodes so the selection ring is never hidden
      const lbl = svg.querySelector(`[data-lbl="${g.selIdx}"]`);
      if(lbl) lbl.parentNode.appendChild(lbl);
      el.parentNode.appendChild(el);
    }
  }
  const focus = g.selIdx;
  if(focus==null){
    svg.querySelectorAll('.dim').forEach(el=>el.classList.remove('dim'));
    return;
  }
  const nbr = new Set([focus]);
  g.edges.forEach(e=>{ if(e.a===focus) nbr.add(e.b); if(e.b===focus) nbr.add(e.a); });
  svg.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('dim', !nbr.has(+el.dataset.node)));
  svg.querySelectorAll('[data-lbl]').forEach(el=>el.classList.toggle('dim', !nbr.has(+el.dataset.lbl)));
  svg.querySelectorAll('[data-e]').forEach(el=>{
    const e = g.edges[+el.dataset.e];
    el.classList.toggle('dim', !(e.a===focus || e.b===focus));
  });
  svg.querySelectorAll('[data-cite-e]').forEach(el=>{
    const e = g.edges[+el.dataset.citeE];
    el.classList.toggle('dim', !(e.a===focus || e.b===focus));
  });
}

function renderGraphSide(){
  const g = graphState;
  const side = $('#graphSide');
  const activeIdx = g && g.hoverIdx!=null ? g.hoverIdx : g && g.selIdx;
  if(!g || activeIdx==null){
    side.innerHTML = `<div class="noselect">${esc(t('graphHint'))}</div>`;
    return;
  }
  const n = g.nodes[activeIdx];
  const it = n.item;
  const inLib = isInLibrary(it);
  const meta1 = [authorsShort(it.authors)].filter(Boolean).join('');
  const meta2 = [it.journal, it.year].filter(Boolean).join(' · ');
  const rel = graphSeedRelation(g, g.selIdx);
  const nearest = graphNearestLinks(g, g.selIdx);
  side.innerHTML = `
    ${n.seed ? `<span class="gsSeedBadge">${esc(t('graphSeed'))}</span>` : ''}
    <div class="gsTitle">${esc(it.title)}</div>
    <div class="gsMeta">${esc(meta1)}</div>
    <div class="gsMeta">${esc(meta2)}</div>
    <div class="gsMeta">${esc(t('colCitedBy'))}: ${n.cited.toLocaleString()}</div>
    ${rel ? `<div class="gsRel"><b>${esc(t('graphRelToSeed'))}</b><br>${esc(graphRelationText(rel))}</div>` : ''}
    ${nearest.length ? `<div class="gsLinks"><b>${esc(t('graphNearest'))}</b>${nearest.map(x=>`<div class="gsLink">${esc(x.node.label || x.node.item.title || '')} · ${esc(I18N[lang].graphSharedRefs(graphEdgeShared(x.edge)))}</div>`).join('')}</div>` : ''}
    <div class="gsBtns">
      ${(it.doi||it.url) ? `<button class="tbtn" data-gs="open">${ic('link')}${esc(t('graphOpenPage'))}</button>` : ''}
      ${n.seed ? '' : `<button class="tbtn" data-gs="graph">${ic('graph')}${esc(t('graphView'))}</button>`}
      ${n.seed ? '' : inLib
        ? `<span class="gsInLib">${ic('check')}${esc(t('citeInLib'))}</span>`
        : `<button class="tbtn" data-gs="add">${ic('plus')}${esc(t('citeAdd'))}</button>`}
    </div>
    ${it.abstract ? `<div class="gsAbsHead">${esc(t('abstract'))}</div><div class="gsAbs">${esc(it.abstract)}</div>` : ''}
  `;
}

function graphCacheKey(item){ return item.doi ? 'doi:'+normDoi(item.doi) : item.arxiv ? 'arxiv:'+item.arxiv : 'id:'+item.id; }
// lean, JSON-serialisable snapshot of a built graph (no Sets / full works)
function leanGraph(data){
  return { nodes: data.nodes.map(n=>({ id:n.id, item:n.item, year:n.year, cited:n.cited, seed:!!n.seed, label:n.label, seedRel:n.seedRel||null })), edges: data.edges };
}
// Generation guard: each open (or refetch) bumps the generation, and a build
// still in flight for an older generation must not touch state/UI afterwards —
// otherwise a slow build A can clobber a dialog that meanwhile shows graph B.
let graphGen = 0;
async function openGraphDialog(item, opts){
  opts = opts || {};
  const gen = ++graphGen;
  $('#graphHeadTitle').textContent = I18N[lang].graphTitle(item.title || t('newItem'));
  const svg = $('#graphSvg');
  svg.innerHTML = '';
  $('#graphStats').textContent = '';
  $('#graphCacheNote').textContent = '';
  graphState = null; graphSeedItem = item;
  populateGraphFilterPanel();
  const fp = $('#graphFilterPanel'); if(fp) fp.hidden = true;
  const sp = $('#graphSettingsPanel'); if(sp) sp.hidden = true;
  renderGraphSide();
  $('#dlgGraph').showModal();

  lib.graphCache = lib.graphCache || {};
  const key = graphCacheKey(item);
  const cached = lib.graphCache[key];
  const cacheUsable = !!(cached && cached.v === GRAPH_CACHE_V && cached.nodes && cached.nodes.length >= 3);
  const useCached = ()=>({ nodes: cached.nodes.map(n=>Object.assign({}, n)), edges: cached.edges });
  let data, fromCache = false;
  if(cacheUsable && !opts.force && isFresh(cached.ts)){
    data = useCached();
    fromCache = true;
  }else{
    $('#graphLoading').textContent = t('graphLoading1');
    let err = null;
    try{
      data = await buildGraphData(item, msg=>{ if(gen===graphGen) $('#graphLoading').textContent = msg; });
    }catch(e){ console.error(e); err = e; }
    if(!err && data.nodes.length < 3) err = { tooFew:true };
    if(!err){
      data.edges = thinEdges(data.nodes, data.edges);
      // persist a lean snapshot so re-opening this graph costs no API calls —
      // even for a superseded build (the data is valid; only the UI is stale).
      // Skipped when too much is missing, so a later retry can heal the gap.
      const wanted = data.nodes.length - 1 + (data.fetchFailed||0);
      if(!data.fetchFailed || data.fetchFailed <= wanted * 0.25){
        lib.graphCache[key] = Object.assign({ ts: new Date().toISOString(), v: GRAPH_CACHE_V }, leanGraph(data));
        // cap the cache: keep the 40 most recent seeds
        const keys = Object.keys(lib.graphCache);
        if(keys.length > 40){
          keys.sort((a,b)=>(lib.graphCache[a].ts||'').localeCompare(lib.graphCache[b].ts||''));
          keys.slice(0, keys.length-40).forEach(k=>delete lib.graphCache[k]);
        }
        touch();
      }
    }
    if(gen !== graphGen) return; // superseded by a newer open / dialog close
    if(err){
      const msg = err.tooFew ? t('graphTooFew') : (err.rateLimited ? t('oaBudgetErr') : t('graphNotFound'));
      if(!cacheUsable){ $('#graphLoading').textContent = msg; return; }
      // keep showing the last good graph (even a stale one) instead of wiping it
      data = useCached();
      fromCache = true;
      showToast(msg);
    }else if(data.fetchFailed){
      showToast(I18N[lang].graphPartial(data.fetchFailed));
    }
  }
  $('#graphLoading').textContent = t('graphLoading3');
  await new Promise(r=>setTimeout(r, 20)); // let the message paint
  if(gen !== graphGen) return;
  // measure the canvas only now (after the build) — right after showModal()
  // the dialog may not have its final size yet. A tiny/hidden viewport gets
  // sane fallbacks; the ResizeObserver below re-layouts once real dims arrive.
  const wrap = $('#graphCanvasWrap');
  let W = wrap.clientWidth, H = wrap.clientHeight;
  if(W < 200 || H < 200){ W = 900; H = 600; }
  graphLayout(data.nodes, data.edges, W, H);
  graphState = { nodes:data.nodes, edges:data.edges, W, H, view:{x:0,y:0,k:1}, selIdx:null };
  populateGraphJournalOptions();
  fitGraphView();
  $('#graphLoading').textContent = '';
  $('#graphCacheNote').textContent = fromCache ? I18N[lang].graphCached(cached.ts.slice(0,10)) : '';
  renderGraph();
}
let graphSeedItem = null;
// closing the dialog abandons any in-flight build (state stays untouched)
$('#dlgGraph').addEventListener('close', ()=>{ graphGen++; });

// interactions: select, pan, zoom, node drag
(function(){
  const svg = $('#graphSvg');
  let pan = null, dragNode = null, moved = false;
  svg.addEventListener('pointerover', (e)=>{
    const nodeEl = e.target.closest('[data-node]');
    if(!graphState || !nodeEl) return;
    const idx = +nodeEl.dataset.node;
    if(graphState.hoverIdx===idx) return;
    graphState.hoverIdx = idx;
    renderGraphSide();
  });
  svg.addEventListener('pointerout', (e)=>{
    const nodeEl = e.target.closest('[data-node]');
    if(!graphState || !nodeEl || nodeEl.contains(e.relatedTarget)) return;
    graphState.hoverIdx = null;
    renderGraphSide();
  });
  svg.addEventListener('pointerdown', (e)=>{
    if(!graphState) return;
    const nodeEl = e.target.closest('[data-node]');
    moved = false;
    if(nodeEl){
      dragNode = { i:+nodeEl.dataset.node, px:e.clientX, py:e.clientY };
    }else{
      pan = { x:e.clientX, y:e.clientY, vx:graphState.view.x, vy:graphState.view.y };
      svg.classList.add('panning');
    }
    svg.setPointerCapture(e.pointerId);
  });
  svg.addEventListener('pointermove', (e)=>{
    if(!graphState) return;
    if(dragNode){
      const k = graphState.view.k;
      const n = graphState.nodes[dragNode.i];
      n.x += (e.clientX - dragNode.px)/k;
      n.y += (e.clientY - dragNode.py)/k;
      const spacingFactor = graphNodeSpacing / 100;
      n.layoutX = graphState.W/2 + (n.x-graphState.W/2)/spacingFactor;
      n.layoutY = graphState.H/2 + (n.y-graphState.H/2)/spacingFactor;
      dragNode.px = e.clientX; dragNode.py = e.clientY;
      moved = true;
      graphState.userView = true;
      renderGraph();
    }else if(pan){
      const k = graphState.view.k;
      graphState.view.x = pan.vx - (e.clientX - pan.x)/k;
      graphState.view.y = pan.vy - (e.clientY - pan.y)/k;
      moved = true;
      graphState.userView = true;
      updateGraphViewBox();
    }
  });
  // double-click detection lives here rather than on the dblclick event —
  // synthetic/touch input often produces two clicks without one
  let lastClick = { i:-1, t:0 };
  svg.addEventListener('pointerup', (e)=>{
    if(dragNode && !moved){
      const i = dragNode.i;
      const now = Date.now();
      if(lastClick.i === i && now - lastClick.t < 400){
        // double-click: rebuild the map around that paper (Connected Papers-style hop)
        lastClick = { i:-1, t:0 };
        const n = graphState.nodes[i];
        dragNode = null; pan = null;
        svg.classList.remove('panning');
        if(n && !n.seed) openGraphDialog(n.item);
        return;
      }
      lastClick = { i, t:now };
      // click: select node (or toggle off)
      graphState.selIdx = graphState.selIdx===dragNode.i ? null : dragNode.i;
      applyHighlight(); renderGraphSide();
    }else if(pan && !moved){
      graphState.selIdx = null;
      applyHighlight(); renderGraphSide();
    }
    dragNode = null; pan = null;
    svg.classList.remove('panning');
  });
  svg.addEventListener('wheel', (e)=>{
    if(!graphState) return;
    e.preventDefault();
    const v = graphState.view;
    const rect = svg.getBoundingClientRect();
    const mx = v.x + (e.clientX - rect.left)/v.k;
    const my = v.y + (e.clientY - rect.top)/v.k;
    const delta = e.deltaY * (e.deltaMode===1 ? 16 : 1);
    const wheelSteps = Math.min(1.5, Math.max(.06, Math.abs(delta)/100));
    const step = 1 + .15 * (graphWheelSensitivity/100);
    const factor = Math.pow(step, wheelSteps);
    const k2 = Math.max(0.3, Math.min(5, v.k * (delta < 0 ? factor : 1/factor)));
    v.x = mx - (e.clientX - rect.left)/k2;
    v.y = my - (e.clientY - rect.top)/k2;
    v.k = k2;
    graphState.userView = true;
    updateGraphViewBox();
  }, {passive:false});
  // Canvas resizes (window resized, or the dialog opened before the window had
  // its final size): update the px ↔ graph-unit mapping immediately, and — as
  // long as the user hasn't started arranging the view by hand — re-run the
  // layout against the new dimensions after the resize settles.
  let roTimer = null;
  new ResizeObserver(()=>{
    const g = graphState;
    if(!g) return;
    const wrap = $('#graphCanvasWrap');
    const W = wrap.clientWidth, H = wrap.clientHeight;
    if(W < 200 || H < 200 || (W===g.W && H===g.H)) return;
    g.W = W; g.H = H;
    updateGraphViewBox();
    if(g.userView) return; // keep a hand-arranged view intact
    clearTimeout(roTimer);
    roTimer = setTimeout(()=>{
      if(graphState !== g) return;
      graphLayout(g.nodes, g.edges, g.W, g.H);
      fitGraphView();
      renderGraph();
    }, 120);
  }).observe($('#graphCanvasWrap'));
})();
